ValidationRule.errorConditionFormula:
OR(
    AND(
        ISPICKVAL(Priority__c, 'P1'),
        NOT(
            OR(
                INCLUDES(Issue_Environment__c, 'PROD'),
                INCLUDES(Issue_Environment__c, 'PreProd')
            )
        )
    ),
    AND(
        ISPICKVAL(Priority__c, 'P2'),
        NOT(
            OR(
                INCLUDES(Issue_Environment__c, 'PROD'),
                INCLUDES(Issue_Environment__c, 'PreProd'),
                INCLUDES(Issue_Environment__c, 'Training')
            )
        )
    )
)
